CREATE TABLE "c_Diagnosis" ("id" BIGINT NOT NULL, "a_Diagnosis_code" TEXT NOT NULL, "a_Diagnosis_description" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Encounter" ("id" BIGINT NOT NULL, "a_Encounter_encounter_date" TIMESTAMP NOT NULL, "r_PatientEncounters_source_id" BIGINT, "r_PatientEncounters_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_PatientEncounters_source_dtype" IS NULL OR "r_PatientEncounters_source_dtype" IN ('Patient')), CHECK ((TRUE) OR "r_PatientEncounters_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_PatientEncounters_source_id" IS NOT NULL));
CREATE TABLE "c_Medication" ("id" BIGINT NOT NULL, "a_Medication_name" TEXT NOT NULL, "a_Medication_dose" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Person" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Clinician_npi" TEXT, "a_Patient_mrn" TEXT, "a_Person_full_name" TEXT, "a_Person_dob" DATE, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Clinician','Patient','Person')), CHECK ((dtype IN ('Clinician')) OR "a_Clinician_npi" IS NULL), CHECK (NOT (dtype IN ('Clinician')) OR "a_Clinician_npi" IS NOT NULL), CHECK ((dtype IN ('Patient')) OR "a_Patient_mrn" IS NULL), CHECK (NOT (dtype IN ('Patient')) OR "a_Patient_mrn" IS NOT NULL), CHECK ((dtype IN ('Clinician','Patient','Person')) OR "a_Person_full_name" IS NULL), CHECK (NOT (dtype IN ('Clinician','Patient','Person')) OR "a_Person_full_name" IS NOT NULL), CHECK ((dtype IN ('Clinician','Patient','Person')) OR "a_Person_dob" IS NULL), CHECK (NOT (dtype IN ('Clinician','Patient','Person')) OR "a_Person_dob" IS NOT NULL));
CREATE TABLE "l_ClinicianEncounters" ("r_ClinicianEncounters_source_id" BIGINT NOT NULL, "r_ClinicianEncounters_source_dtype" TEXT NOT NULL, "r_ClinicianEncounters_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ClinicianEncounters_source_id", "r_ClinicianEncounters_target_id"), UNIQUE ("r_ClinicianEncounters_target_id"), CHECK ("r_ClinicianEncounters_source_dtype" IS NULL OR "r_ClinicianEncounters_source_dtype" IN ('Clinician')));
CREATE TABLE "l_EncounterDiagnoses" ("r_EncounterDiagnoses_source_id" BIGINT NOT NULL, "r_EncounterDiagnoses_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_EncounterDiagnoses_source_id", "r_EncounterDiagnoses_target_id"));
CREATE TABLE "l_EncounterMedications" ("r_EncounterMedications_source_id" BIGINT NOT NULL, "r_EncounterMedications_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_EncounterMedications_source_id", "r_EncounterMedications_target_id"));
ALTER TABLE "c_Encounter" ADD CONSTRAINT "fk_c_Encounter_0" FOREIGN KEY ("r_PatientEncounters_source_id", "r_PatientEncounters_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ClinicianEncounters" ADD CONSTRAINT "fk_l_ClinicianEncounters_0" FOREIGN KEY ("r_ClinicianEncounters_source_id", "r_ClinicianEncounters_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ClinicianEncounters" ADD CONSTRAINT "fk_l_ClinicianEncounters_1" FOREIGN KEY ("r_ClinicianEncounters_target_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterDiagnoses" ADD CONSTRAINT "fk_l_EncounterDiagnoses_0" FOREIGN KEY ("r_EncounterDiagnoses_source_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterDiagnoses" ADD CONSTRAINT "fk_l_EncounterDiagnoses_1" FOREIGN KEY ("r_EncounterDiagnoses_target_id") REFERENCES "c_Diagnosis" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterMedications" ADD CONSTRAINT "fk_l_EncounterMedications_0" FOREIGN KEY ("r_EncounterMedications_source_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterMedications" ADD CONSTRAINT "fk_l_EncounterMedications_1" FOREIGN KEY ("r_EncounterMedications_target_id") REFERENCES "c_Medication" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_ClinicianEncounters"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Encounter" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_ClinicianEncounters" l WHERE l."r_ClinicianEncounters_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: ClinicianEncounters'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_ClinicianEncounters_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Encounter" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ClinicianEncounters"();
CREATE CONSTRAINT TRIGGER "ct_ClinicianEncounters_link" AFTER INSERT OR UPDATE OR DELETE ON "l_ClinicianEncounters" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ClinicianEncounters"();